$nombre=$_SESSION['nombre'] ?? 'Administrador'; $rol=$_SESSION['rol']; $mensaje=''; $error=false;
function e($v){ return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); }
function postInt($k){ return filter_input(INPUT_POST,$k,FILTER_VALIDATE_INT) ?: 0; }
function auditUser(PDO $pdo){ $s=$pdo->prepare('SET @usuario_app = ?'); $s->execute([$_SESSION['usuario']]); }
function friendly(PDOException $e){ $m=$e->getMessage(); if(stripos($m,'Duplicate')!==false) return 'Ya existe un registro con alguno de los datos únicos proporcionados.'; if(stripos($m,'materias requisito')!==false) return 'El alumno no cumple con los prerrequisitos necesarios para esta materia.'; return 'No fue posible completar la operación. Verifica los datos y sus relaciones.'; }
try{if($_SERVER['REQUEST_METHOD']==='POST'){ $a=$_POST['accion']??''; if($a==='carrera'){ $id=postInt('id');$n=trim($_POST['nombre']??'');$ap=strtoupper(trim($_POST['apodo']??''));if(!$n||!$ap)throw new Exception('Datos incompletos.');$s=$id?$pdo->prepare('UPDATE carreras SET nombre=?,apodo=? WHERE id=?'):$pdo->prepare('INSERT INTO carreras(nombre,apodo) VALUES(?,?)');$s->execute($id?[$n,$ap,$id]:[$n,$ap]);$mensaje='Carrera guardada.';} if($a==='materia'){ $id=postInt('id');$n=trim($_POST['nombre']??'');$cl=strtoupper(trim($_POST['clave']??''));$cr=(int)($_POST['creditos']??0);if(!$n||!$cl||$cr<1||$cr>12)throw new Exception('Materia inválida.');$s=$id?$pdo->prepare('UPDATE materias SET nombre=?,clave=?,creditos=? WHERE id=?'):$pdo->prepare('INSERT INTO materias(nombre,clave,creditos) VALUES(?,?,?)');$s->execute($id?[$n,$cl,$cr,$id]:[$n,$cl,$cr]);$mensaje='Materia guardada.';} if($a==='plan'){ $s=$pdo->prepare('INSERT INTO carrera_materia(carrera,materias,semestre) VALUES(?,?,?) ON DUPLICATE KEY UPDATE semestre=VALUES(semestre)');$s->execute([postInt('carrera'),postInt('materia'),(int)$_POST['semestre']]);$mensaje='Plan actualizado.';} if($a==='seriacion'){ $m=postInt('materia');$r=postInt('requisito');if(!$m||!$r||$m===$r)throw new Exception('La materia y su requisito deben ser diferentes.');$s=$pdo->prepare('INSERT INTO materia_seriacion(materia,materia_requisito) VALUES(?,?)');$s->execute([$m,$r]);$mensaje='Seriación registrada.';} }}catch(PDOException $e){$error=true;$mensaje=friendly($e);}catch(Exception $e){$error=true;$mensaje=$e->getMessage();}$carreras=$pdo->query('SELECT * FROM carreras ORDER BY nombre')->fetchAll();$materias=$pdo->query('SELECT * FROM materias ORDER BY nombre')->fetchAll();$plan=$pdo->query('SELECT cm.*,c.nombre carrera_nombre,m.nombre materia_nombre FROM carrera_materia cm JOIN carreras c ON c.id=cm.carrera JOIN materias m ON m.id=cm.materias ORDER BY c.nombre,cm.semestre,m.nombre')->fetchAll();$seriaciones=$pdo->query('SELECT m.nombre materia,r.nombre requisito FROM materia_seriacion s JOIN materias m ON m.id=s.materia JOIN materias r ON r.id=s.materia_requisito ORDER BY m.nombre')->fetchAll();
